window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[123]={"id":"123","numero":123,"titre":"Vieillissement normal","objectifs":[{"id":"123-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du vieillissement","contenu":"<p>Le <span class=\"kw-def\"><strong>vieillissement</strong></span> est l'<span class=\"kw-def\">ensemble des processus physiologiques</span> qui modifient la <span class=\"kw-def\">structure</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">fonctions de l'organisme</span> à partir de l'<span class=\"kw-chiffre\">âge mûr</span>. C'est un processus <span class=\"kw-clinique\">lent et progressif</span>, à distinguer des maladies.</p>\n      <p>Il est la <span class=\"kw-def\">résultante</span> de plusieurs catégories de facteurs subis tout au long de la vie :</p>\n      <ul>\n        <li><span class=\"kw-etio\">facteurs génétiques</span></li>\n        <li><span class=\"kw-etio\">facteurs environnementaux</span></li>\n        <li><span class=\"kw-etio\">facteurs aléatoires (stochastiques)</span></li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Vieillissement et maladies</strong>\n        <ul>\n          <li>Le vieillissement n'est <strong>pas</strong> une maladie, mais ses <span class=\"kw-clinique\">altérations</span> favorisent <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">maladies chroniques</span> et les <span class=\"kw-alerte\">décompensations aiguës</span>.</li>\n          <li>C'est un <span class=\"kw-def\">facteur de vulnérabilité</span> face à un stress.</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-danger\">\n        <strong>Point-clé (incontournable)</strong>\n        <p>Le vieillissement n'est <span class=\"kw-alerte\">JAMAIS responsable seul d'une symptomatologie aiguë</span> : l'âge n'explique à lui seul ni une <span class=\"kw-clinique\">dyspnée</span>, ni une <span class=\"kw-clinique\">chute</span>, ni une <span class=\"kw-clinique\">confusion</span>. Une cause doit toujours être recherchée.</p>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 130 — Personne âgée malade · 131 — Troubles de la marche et de l'équilibre du sujet âgé · 132 — Troubles cognitifs du sujet âgé</em></p>","frequence":0},{"id":"123-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la gérontologie","contenu":"<p>La <span class=\"kw-def\"><strong>gérontologie</strong></span> est l'<span class=\"kw-def\">étude du vieillissement dans tous ses aspects</span>. C'est un champ situé au <span class=\"kw-def\">carrefour de nombreuses sciences</span>.</p>\n      <p><strong>Aspects étudiés</strong></p>\n      <ul>\n        <li>aspect <span class=\"kw-def\">biomédical</span></li>\n        <li>aspect <span class=\"kw-def\">sociologique</span></li>\n        <li>aspect <span class=\"kw-def\">géographique</span></li>\n        <li>aspect <span class=\"kw-def\">économique</span></li>\n        <li>aspect <span class=\"kw-def\">culturel</span></li>\n        <li>aspect <span class=\"kw-def\">démographique</span></li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Sciences contributrices</strong>\n        <p><span class=\"kw-def\">médecine</span>, <span class=\"kw-def\">sociologie</span>, <span class=\"kw-def\">psychologie</span>, <span class=\"kw-def\">économie</span>, <span class=\"kw-def\">démographie</span>, <span class=\"kw-def\">anthropologie</span>.</p>\n      </div>","frequence":0},{"id":"123-3","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la gériatrie et du raisonnement gériatrique (schéma J.P. Bouchon)","contenu":"<p>La <span class=\"kw-def\"><strong>gériatrie</strong></span> est la <span class=\"kw-def\">médecine des personnes âgées</span> (spécialité médicale).</p>\n      <p>Le <span class=\"kw-def\"><strong>raisonnement gériatrique</strong></span> repose sur le <span class=\"kw-def\">modèle de décompensation « 1 + 2 + 3 » de J.P. Bouchon</span> : la <span class=\"kw-alerte\">décompensation</span> survient quand <span class=\"kw-clinique\">les</span> facteurs s'<span class=\"kw-clinique\">additionnent</span> (<span class=\"kw-chiffre\">1+2+3</span> ou <span class=\"kw-chiffre\">1+3</span>).</p>\n      <table >\n        <thead><tr><th>Facteur</th><th>Nature</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>1</strong></span></td>\n            <td><span class=\"kw-def\">Vieillissement physiologique de l'organe</span></td>\n            <td>Déclin <span class=\"kw-clinique\">très progressif</span> ;<br>le <span class=\"kw-alerte\">seuil d'insuffisance d'organe n'est jamais atteint</span> par le seul vieillissement</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>2</strong></span></td>\n            <td><span class=\"kw-etio\">Maladie chronique</span></td>\n            <td>Diminue plus vite la <span class=\"kw-def\">réserve fonctionnelle</span> → source de <span class=\"kw-def\">vulnérabilité</span> ;<br>peut être <strong>absente</strong> chez le très âgé (→ schéma <span class=\"kw-chiffre\">1+3</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>3</strong></span></td>\n            <td><span class=\"kw-etio\">Facteur précipitant</span></td>\n            <td><span class=\"kw-alerte\">Situation aiguë</span> qui rend symptomatique ;<br>facteur le plus <span class=\"kw-clinique\">accessible à une intervention</span> (souvent <span class=\"kw-clinique\">réversible</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Devant une <span class=\"kw-alerte\">décompensation</span> aiguë du sujet âgé, c'est le <span class=\"kw-etio\">facteur 3 (précipitant)</span> qu'il faut traquer et corriger : il est souvent réversible et son traitement permet le retour à l'état antérieur.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 130 — Personne âgée malade · 133 — Autonomie-dépendance du sujet âgé</em></p>","frequence":3},{"id":"123-4","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l'âge de la vieillesse","contenu":"<p>Il n'existe pas de seuil unique : l'<span class=\"kw-def\">âge de la vieillesse</span> dépend du <span class=\"kw-def\">contexte</span> considéré.</p>\n      <table >\n        <thead><tr><th>Seuil</th><th>Contexte</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">60 ans</span></td><td><span class=\"kw-def\">Prestations sociales</span> en France</td></tr>\n          <tr><td><span class=\"kw-chiffre\">65 ans</span></td><td>Définition de l'<span class=\"kw-def\">OMS</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">75 ans</span></td><td>Seuil de <span class=\"kw-alerte\">risque de perte d'autonomie et de fragilité</span> ;<br>âge d'<span class=\"kw-def\">entrée en service de gériatrie</span> (moyenne réelle <span class=\"kw-chiffre\">&gt; 80 ans</span>)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 130 — Personne âgée malade · 133 — Autonomie-dépendance du sujet âgé</em></p>","frequence":0},{"id":"123-5","rang":"A","rubrique":"Définition","titre":"Connaître la définition démographique","contenu":"<p>Plusieurs <span class=\"kw-def\">indicateurs démographiques</span> permettent de quantifier le vieillissement d'une population.</p>\n      <table >\n        <thead><tr><th>Notion</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Longévité moyenne</strong></span></td><td>Durée de vie <span class=\"kw-def\">biologiquement programmée</span> en conditions idéales</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Longévité maximale</strong></span></td><td>Durée de vie <span class=\"kw-def\">maximale observée</span> : <span class=\"kw-chiffre\">122 ans</span> pour l'Homme</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Espérance de vie à la naissance</strong></span></td><td>Homme <span class=\"kw-chiffre\">79 ans</span>, Femme <span class=\"kw-chiffre\">85 ans</span><br>(année où <span class=\"kw-chiffre\">50 %</span> de la cohorte née la même année décède − année de naissance)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Espérance de vie sans incapacité</strong></span></td><td>Délai pour que <span class=\"kw-chiffre\">50 %</span> des personnes décèdent <strong>ou</strong> soient atteintes d'<span class=\"kw-clinique\">incapacité</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Tendance.</strong> L'<span class=\"kw-clinique\">allongement de la vie</span> s'accompagne d'une <span class=\"kw-clinique\">diminution du nombre moyen d'années vécues en incapacité</span>.</div>","frequence":0},{"id":"123-6","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les données d'espérance de vie en France","contenu":"<p>Données d'<span class=\"kw-def\">espérance de vie (EV)</span> en France.</p>\n      <table >\n        <thead><tr><th>Indicateur</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">EV à la naissance (2020)</span></td><td>Femmes <span class=\"kw-chiffre\">85,2 ans</span><br>Hommes <span class=\"kw-chiffre\">79,2 ans</span></td></tr>\n          <tr><td><span class=\"kw-def\">EV à 60 ans</span></td><td>Femmes <span class=\"kw-chiffre\">27 ans</span><br>Hommes <span class=\"kw-chiffre\">23 ans</span></td></tr>\n          <tr><td><span class=\"kw-def\">Progression</span></td><td><span class=\"kw-chiffre\">+ 1,3 an tous les 10 ans</span></td></tr>\n          <tr><td><span class=\"kw-def\">Longévité maximale humaine</span></td><td><span class=\"kw-chiffre\">122 ans 6 mois</span> (Jeanne-Louise Calment, record <span class=\"kw-chiffre\">1997</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-clinique\">Évolution</span> au XXᵉ siècle</strong></p>\n      <ul>\n        <li>EV à la naissance passée de <span class=\"kw-chiffre\">47 ans</span> à <span class=\"kw-chiffre\">~ 80 ans</span></li>\n        <li>Liée à la <span class=\"kw-clinique\">réduction drastique de la mortalité précoce</span> : <span class=\"kw-etio\">mortalité infantile</span> + <span class=\"kw-etio\">mortalité infectieuse</span></li>\n        <li>Grâce à l'<span class=\"kw-clinique\">hygiène</span> et à la <span class=\"kw-clinique\">médecine</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Chez <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&gt; 80 ans</span>.</strong> L'<span class=\"kw-clinique\">EV totale</span> et l'<span class=\"kw-clinique\">EV sans incapacité</span> augmentent toutes les deux.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":1},{"id":"123-7","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les principales conséquences économiques et sociales du vieillissement","contenu":"<p>Le vieillissement de la population a des <span class=\"kw-def\">conséquences économiques</span> et <span class=\"kw-def\">sociales</span> majeures.</p>\n      <p><strong>Conséquences économiques</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Dépenses de santé</span> : <span class=\"kw-clinique\">les</span> personnes âgées sont de gros consommateurs de soins et d'hospitalisations</li>\n        <li><span class=\"kw-clinique\">Coût des prestations sociales</span>, notamment l'<span class=\"kw-def\">APA (allocation personnalisée d'autonomie)</span></li>\n        <li><span class=\"kw-clinique\">Besoins de places en institutions</span> (<span class=\"kw-def\">EHPAD</span>)</li>\n        <li><span class=\"kw-clinique\">Financement des retraites</span> : <span class=\"kw-clinique\">les</span> cotisations des actifs financent les retraites → <span class=\"kw-clinique\">recul de l'âge de départ</span></li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>« Silver économie »</strong>\n        <p>Filière économique née du vieillissement : <span class=\"kw-clinique\">aide à domicile</span>, <span class=\"kw-clinique\">établissements gériatriques</span>, <span class=\"kw-clinique\">secteur médico-social</span>, <span class=\"kw-clinique\">géronto-technologies</span>.</p>\n      </div>\n      <p><strong>Conséquences sociales</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Familles à 4-5 générations</span></li>\n        <li>Génération de <span class=\"kw-clinique\">jeunes retraités en bonne santé</span> (bénévolat, vie politique, associations)</li>\n        <li><span class=\"kw-def\">Représentation sociale ambivalente</span> : négative (affaibli, inutile, improductif) <em><span class=\"kw-bio\">vs</span></em> positive (« patriarche », sagesse, expérience, transmission)</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":0},{"id":"123-8","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l'âgisme","contenu":"<p>L'<span class=\"kw-def\"><strong>âgisme</strong></span> est une <span class=\"kw-alerte\">attitude de discrimination négative</span> envers <span class=\"kw-clinique\">les</span> personnes âgées <span class=\"kw-etio\">du fait de leur âge</span>.</p>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-clinique\">Évolution</span>.</strong> L'âgisme est en <span class=\"kw-clinique\">voie de régression</span>, avec le <span class=\"kw-etio\">vieillissement de la population</span> et l'<span class=\"kw-etio\">évolution des connaissances</span>.</div>","frequence":0},{"id":"123-9","rang":"A","rubrique":"Définition","titre":"Connaître les notions de vulnérabilité ou fragilité","contenu":"<p>La <span class=\"kw-def\"><strong>vulnérabilité</strong></span> est la <span class=\"kw-def\">diminution des capacités de réserve fonctionnelle</span> de l'organisme.</p>\n      <div class=\"callout callout-info\">\n        <strong>Mécanisme</strong>\n        <ul>\n          <li>En <span class=\"kw-clinique\">conditions basales</span>, la personne âgée reste <span class=\"kw-clinique\">asymptomatique</span>.</li>\n          <li>La vulnérabilité se <span class=\"kw-clinique\">démasque lors d'une agression</span> (<span class=\"kw-etio\">effort</span>, <span class=\"kw-etio\">stress</span>, <span class=\"kw-etio\">maladie aiguë</span>) → la personne devient <span class=\"kw-clinique\">symptomatique</span> ou de <span class=\"kw-alerte\">moins bon pronostic</span>.</li>\n        </ul>\n      </div>\n      <p><strong>Deux origines de la vulnérabilité</strong></p>\n      <ul>\n        <li>vulnérabilité <span class=\"kw-etio\">induite par le vieillissement</span></li>\n        <li>vulnérabilité <span class=\"kw-etio\">induite par les séquelles de maladies passées</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">conséquences des maladies chroniques</span></li>\n      </ul>\n      <p>La <span class=\"kw-def\"><strong>fragilité</strong></span> est un <span class=\"kw-def\">syndrome gériatrique</span> facilement <span class=\"kw-clinique\">mesurable</span>, qui permet d'appréhender globalement la vulnérabilité (<span class=\"kw-chiffre\">≥ 3 des 5 critères de Fried</span>).</p>\n      <div class=\"callout callout-info\">\n        <strong>Propriétés de la fragilité</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Toutes les personnes âgées ne sont pas fragiles.</span></li>\n          <li>Associée à un <span class=\"kw-alerte\">déclin fonctionnel</span> et à un <span class=\"kw-alerte\">risque d'institutionnalisation</span>.</li>\n          <li><span class=\"kw-clinique\">Potentiellement réversible</span> : <span class=\"kw-ttt\">nutrition</span>, <span class=\"kw-ttt\">activité physique</span>, <span class=\"kw-ttt\">activité sociale</span>, <span class=\"kw-ttt\">traitements</span>.</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 130 — Personne âgée malade · 133 — Autonomie-dépendance du sujet âgé</em></p>","frequence":1},{"id":"123-10","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les généralités sur la physiopathologie du vieillissement","contenu":"<p><strong>Principe général.</strong> Avec l'âge, on observe une <span class=\"kw-clinique\">augmentation des agressions / lésions</span> et une <span class=\"kw-clinique\">diminution des capacités de correction / réparation</span>.</p>\n      <p><strong>Lésions de l'ADN</strong></p>\n      <ul>\n        <li>portent sur l'<span class=\"kw-bio\">ADN nucléaire</span> et l'<span class=\"kw-bio\">ADN mitochondrial</span></li>\n        <li><span class=\"kw-etio\">facteurs endogènes</span> : liés à la <span class=\"kw-bio\">réplication cellulaire</span> et aux <span class=\"kw-bio\">radicaux libres</span></li>\n        <li><span class=\"kw-etio\">facteurs exogènes</span> : <span class=\"kw-etio\">environnementaux</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Équilibre lésions / réparation.</strong> C'est lui qui détermine <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">rythmes de vieillissement des organes</span>. Il dépend à la fois de <span class=\"kw-etio\">facteurs génétiques</span> ET de <span class=\"kw-etio\">facteurs environnementaux</span>.</div>","frequence":1},{"id":"123-11","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les principaux mots-clés du vieillissement d'organes","contenu":"<p>Synthèse des <span class=\"kw-def\">« mots-clés »</span> du vieillissement par appareil (le détail figure dans l'objectif « modifications des organes »).</p>\n      <table >\n        <thead><tr><th>Appareil</th><th>Mot-clé</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Muscle</span></td><td><span class=\"kw-clinique\">sarcopénie</span></td></tr>\n          <tr><td><span class=\"kw-def\">Sens</span></td><td><span class=\"kw-clinique\">presbytie</span>, <span class=\"kw-clinique\">cataracte</span>, <span class=\"kw-clinique\">presbyacousie</span></td></tr>\n          <tr><td><span class=\"kw-def\">Respiratoire</span></td><td><span class=\"kw-clinique\">baisse de la capacité ventilatoire</span></td></tr>\n          <tr><td><span class=\"kw-def\">Digestif</span></td><td><span class=\"kw-clinique\">hypochlorhydrie gastrique</span></td></tr>\n          <tr><td><span class=\"kw-def\">Rein</span></td><td><span class=\"kw-clinique\">réduction néphronique</span>, <span class=\"kw-bio\">baisse du DFG</span></td></tr>\n          <tr><td><span class=\"kw-def\">Peau</span></td><td><span class=\"kw-clinique\">baisse des mélanocytes</span>, <span class=\"kw-clinique\">sécheresse cutanée</span></td></tr>\n          <tr><td><span class=\"kw-def\">Immunité</span></td><td><span class=\"kw-clinique\">inflammaging</span>, <span class=\"kw-clinique\">immunosénescence</span></td></tr>\n          <tr><td><span class=\"kw-def\">Système autonome</span></td><td><span class=\"kw-clinique\">baisse du baroréflexe</span> → <span class=\"kw-alerte\">hypotension orthostatique</span></td></tr>\n          <tr><td><span class=\"kw-def\">Os</span></td><td><span class=\"kw-clinique\">ostéopénie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>À insister.</strong> Le <span class=\"kw-clinique\">vieillissement physiologique</span> ne <span class=\"kw-alerte\">franchit jamais seul le seuil d'insuffisance d'organe</span>.</div>","frequence":0},{"id":"123-12","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les intrications vieillissement cardio-vasculaire / conséquences cliniques","contenu":"<p>Le vieillissement <span class=\"kw-def\">cardio-vasculaire</span> associe des modifications <span class=\"kw-def\">artérielles</span> et <span class=\"kw-def\">cardiaques</span>, dont découlent des conséquences cliniques.</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Modifications et conséquences</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Artériel</strong></span></td>\n            <td><span class=\"kw-etio\">Altérations de la matrice extracellulaire</span> : désorganisation de l'<span class=\"kw-bio\">élastine</span>, <span class=\"kw-bio\">glycation du collagène</span><br>→ <span class=\"kw-clinique\">rigidité des gros troncs artériels</span> + <span class=\"kw-clinique\">augmentation des résistances périphériques</span><br>→ <span class=\"kw-clinique\">augmentation de la PAS</span> et de la <span class=\"kw-clinique\">pression pulsée (PP)</span> ; la <span class=\"kw-clinique\">PAD n'augmente plus après <span class=\"kw-chiffre\">50 ans</span></span><br>→ <span class=\"kw-clinique\">augmentation de la vélocité de l'onde de pouls</span><br>→ favorise l'<span class=\"kw-alerte\">HTA systolique</span> et l'<span class=\"kw-alerte\">HVG</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Cardiaque</strong></span></td>\n            <td><span class=\"kw-clinique\">Trouble de la relaxation myocardique</span> (défaut de compliance) → <span class=\"kw-clinique\">défaut de remplissage du VG</span><br>La <span class=\"kw-clinique\">systole auriculaire</span> devient le principal mécanisme de remplissage après <span class=\"kw-chiffre\">80 ans</span><br><span class=\"kw-alerte\">Troubles du rythme et de conduction</span> plus fréquents (zones de fibrose)<br><span class=\"kw-clinique\">Moins bonne tolérance à l'effort</span> (baisse de la <span class=\"kw-bio\">FC maximale</span>)<br><span class=\"kw-alerte\">Plus grande sensibilité à l'ischémie myocardique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Inchangé</strong></span></td>\n            <td>Ne changent PAS avec le vieillissement : <span class=\"kw-bio\">débit cardiaque de repos</span>, <span class=\"kw-bio\">FC de repos</span>, <span class=\"kw-bio\">fraction d'éjection</span></td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"123-13","rang":"B","rubrique":"Définition","titre":"Connaître la définition de la biologie du vieillissement","contenu":"<p>La <span class=\"kw-def\"><strong>biologie du vieillissement</strong></span> est l'<span class=\"kw-def\">étude des mécanismes et des manifestations du vieillissement</span>.</p>\n      <p><strong>Modèles d'étude</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">in vitro</span> : sur des <span class=\"kw-bio\">modèles cellulaires et tissulaires</span></li>\n        <li><span class=\"kw-bio\">in vivo</span> : chez l'<span class=\"kw-bio\">animal expérimental</span> et chez l'<span class=\"kw-bio\">Homme</span></li>\n      </ul>","frequence":0},{"id":"123-14","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la fragilité selon Fried (critères) et du déclin fonctionnel","contenu":"<p>La <span class=\"kw-def\"><strong>fragilité selon Fried</strong></span> repose sur <span class=\"kw-chiffre\">5 critères</span>.</p>\n      <table >\n        <thead><tr><th>#</th><th><span class=\"kw-def\">Critère de</span> Fried</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">1</span></td><td><span class=\"kw-clinique\">Perte de poids involontaire</span> dans la dernière année</td></tr>\n          <tr><td><span class=\"kw-chiffre\">2</span></td><td><span class=\"kw-clinique\">Impression subjective de fatigue</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">3</span></td><td><span class=\"kw-clinique\">Réduction des activités physiques</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">4</span></td><td><span class=\"kw-clinique\">Diminution de la force musculaire</span> (mesurée par <span class=\"kw-bio\">hand grip</span>)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">5</span></td><td><span class=\"kw-clinique\">Diminution de la vitesse de marche</span> (<span class=\"kw-chiffre\">&lt; 0,8 m/s</span> = <span class=\"kw-alerte\">élément le plus déterminant</span>, prédit à elle seule la <span class=\"kw-def\">mortalité</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Interprétation</strong></p>\n      <table >\n        <thead><tr><th>Statut</th><th>Nombre de critères</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Robuste (non fragile)</span></td><td><span class=\"kw-chiffre\">0 critère</span></td></tr>\n          <tr><td><span class=\"kw-def\">Préfragile</span></td><td><span class=\"kw-chiffre\">1-2 critères</span></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Fragile</strong></span></td><td><span class=\"kw-chiffre\">≥ 3 critères</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Déclin fonctionnel</strong>\n        <ul>\n          <li><span class=\"kw-def\">Réduction multisystémique des réserves fonctionnelles.</span></li>\n          <li>La <span class=\"kw-clinique\">fragilité</span> est un <span class=\"kw-def\">état précurseur de la dépendance fonctionnelle</span>.</li>\n          <li>Proportion de sujets fragiles à <span class=\"kw-chiffre\">65 ans</span> ≈ <span class=\"kw-chiffre\">15 %</span>.</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 130 — Personne âgée malade · 131 — Troubles de la marche et de l'équilibre du sujet âgé · 133 — Autonomie-dépendance du sujet âgé</em></p>","frequence":2},{"id":"123-15","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les mécanismes biologiques à l'origine du vieillissement","contenu":"<p><span class=\"kw-clinique\">Les</span> grands <span class=\"kw-def\">mécanismes biologiques (hallmarks)</span> du vieillissement s'organisent en <span class=\"kw-chiffre\">3 groupes</span>.</p>\n      <table >\n        <thead><tr><th>Groupe</th><th>Mécanismes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>1. Mécanismes moléculaires primaires</strong></span></td>\n            <td><span class=\"kw-def\">Instabilité génomique</span><br><span class=\"kw-def\">Attrition (raccourcissement) des télomères</span><br><span class=\"kw-def\">Altérations épigénétiques</span><br><span class=\"kw-def\">Perte de protéostasie</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>2. Mécanismes antagonistes</strong></span> (réponses aux lésions)</td>\n            <td><span class=\"kw-def\">Sénescence cellulaire</span> (théorie de <span class=\"kw-def\">Hayflick</span>) : massive au grand âge → remplacement par tissus moins fonctionnels / <span class=\"kw-clinique\">fibrose</span> ; cellules sénescentes pro-inflammatoires → <span class=\"kw-clinique\">inflamm-aging</span><br><span class=\"kw-def\">Dysfonction mitochondriale</span> (↑ <span class=\"kw-bio\">radicaux libres</span> ; mécanisme secondaire)<br><span class=\"kw-def\">Dérégulation de la détection des nutriments</span> (protéine kinase <span class=\"kw-bio\">TOR / mTOR</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>3. Facteurs intégratifs</strong></span></td>\n            <td><span class=\"kw-def\">Épuisement des cellules souches</span> (<span class=\"kw-clinique\">anémies</span>, <span class=\"kw-clinique\">immunosénescence</span>, <span class=\"kw-clinique\">athérome</span>, <span class=\"kw-clinique\">ostéoporose</span>, <span class=\"kw-clinique\">sarcopénie</span>, <span class=\"kw-clinique\">maladies neurodégénératives</span>)<br><span class=\"kw-def\">Altération de la communication intercellulaire</span> (<span class=\"kw-clinique\">immunosénescence</span>, <span class=\"kw-clinique\">inflamm-aging</span>, <span class=\"kw-clinique\">baisse de la plasticité neuronale</span>, signalisation <span class=\"kw-bio\">rénine-angiotensine</span> / <span class=\"kw-bio\">insuline-IGF1</span>)</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"123-16","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les modifications reconnues liées au vieillissement des organes","contenu":"<p><span class=\"kw-def\">Modifications reconnues</span> du vieillissement, appareil par appareil.</p>\n      <table >\n        <thead><tr><th>Appareil / système</th><th>Modifications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Métabolisme</strong></span></td>\n            <td><span class=\"kw-clinique\">Sarcopénie</span> : ↓ <span class=\"kw-clinique\">masse</span> / <span class=\"kw-clinique\">force</span> / <span class=\"kw-clinique\">performance musculaire</span> (la perte de performance est plus rapide que celle de force / <span class=\"kw-clinique\">masse</span>)<br>↑ <span class=\"kw-clinique\">masse grasse viscérale</span><br>↑ <span class=\"kw-bio\">insulinorésistance</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Sens</strong></span></td>\n            <td><span class=\"kw-clinique\">Presbytie</span>, <span class=\"kw-clinique\">cataracte</span>, <span class=\"kw-clinique\">presbyacousie</span> (portant principalement sur <span class=\"kw-clinique\">les</span> sons aigus)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Respiratoire</strong></span></td>\n            <td>↓ <span class=\"kw-clinique\">capacité ventilatoire</span> : ↓ <span class=\"kw-clinique\">compliance pulmonaire / thoracique</span>, ↓ <span class=\"kw-clinique\">muscles respiratoires</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Digestif</strong></span></td>\n            <td>Modifs <span class=\"kw-clinique\">bucco-dentaires</span><br>↓ <span class=\"kw-bio\">flux salivaire</span><br><span class=\"kw-clinique\">Hypochlorhydrie gastrique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Rein</strong></span></td>\n            <td>↓ <span class=\"kw-clinique\">taille / masse rénale</span> (surtout corticale)<br><span class=\"kw-clinique\">Réduction néphronique</span> : <span class=\"kw-chiffre\">−20 à 40 %</span> des glomérules à <span class=\"kw-chiffre\">70 ans</span><br>↓ <span class=\"kw-bio\">DFG</span> de <span class=\"kw-chiffre\">0,5 à 1 mL/min/1,73 m²/an</span> dès <span class=\"kw-chiffre\">50 ans</span><br>↓ <span class=\"kw-clinique\">adaptation à la perte d'eau / sel</span> et au <span class=\"kw-clinique\">pouvoir de concentration / dilution</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Peau / phanères</strong></span></td>\n            <td>↓ <span class=\"kw-clinique\">mélanocytes</span><br><span class=\"kw-clinique\">Sécheresse cutanée</span><br>↓ <span class=\"kw-clinique\">croissance cheveux / ongles</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Organes sexuels</strong></span></td>\n            <td><span class=\"kw-clinique\">Ménopause</span>, <span class=\"kw-clinique\">andropause</span><br>↑ <span class=\"kw-clinique\">volume prostatique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Système immunitaire</strong></span></td>\n            <td>Inné : <span class=\"kw-clinique\">état pro-inflammatoire</span> = <span class=\"kw-clinique\">inflammaging</span><br>Adaptatif : <span class=\"kw-clinique\">involution thymique</span>, ↓ <span class=\"kw-bio\">cellules naïves</span>, ↓ <span class=\"kw-bio\">taux / affinité des anticorps</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>SNC</strong></span></td>\n            <td>↓ modérée des <span class=\"kw-clinique\">performances mnésiques</span> SANS retentissement sur la vie quotidienne<br>↑ <span class=\"kw-clinique\">temps de réaction</span>, ↓ <span class=\"kw-clinique\">attention en double tâche</span><br><span class=\"kw-clinique\">Fragmentation du sommeil</span> / avance de phase<br>↓ <span class=\"kw-clinique\">sensation de soif</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>SNP</strong></span></td>\n            <td>↓ <span class=\"kw-clinique\">proprioception</span> → <span class=\"kw-alerte\">instabilité posturale</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>SN autonome</strong></span></td>\n            <td>↓ <span class=\"kw-clinique\">baroréflexe</span> → <span class=\"kw-alerte\">hypotension orthostatique</span><br>↓ <span class=\"kw-bio\">FC max à l'effort</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Os</strong></span></td>\n            <td><span class=\"kw-clinique\">Ostéopénie</span>, ↓ <span class=\"kw-bio\">DMO</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Cartilage</strong></span></td>\n            <td><span class=\"kw-clinique\">Amincissement</span>, <span class=\"kw-clinique\">altération mécanique</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 124 — Ménopause - andropause · 126 — Trouble érection · 128 — Ostéopathie fragilisante · 129 — Arthrose</em></p>","frequence":1},{"id":"123-17","rang":"B","rubrique":"Prise en charge","titre":"Connaître les grandes stratégies de prévention du vieillissement","contenu":"<div class=\"callout callout-info\">\n        <strong>Deux éléments clés pour bien vieillir</strong>\n        <ul>\n          <li>maintien / reprise d'une <span class=\"kw-ttt\">activité physique adaptée</span></li>\n          <li><span class=\"kw-ttt\">alimentation adaptée</span></li>\n        </ul>\n      </div>\n      <table >\n        <thead><tr><th>Stratégie</th><th>Effet / niveau de preuve</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Activité physique</strong></span></td>\n            <td>S'oppose à plusieurs effets du vieillissement (<span class=\"kw-clinique\">muscle</span>, <span class=\"kw-clinique\">os</span>, <span class=\"kw-clinique\">métabolisme</span>, <span class=\"kw-clinique\">respiratoire</span>, <span class=\"kw-clinique\">cognitif</span>)<br><span class=\"kw-clinique\">Bénéfique même débutée tardivement</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Restriction calorique</strong></span></td>\n            <td>Ralentit le vieillissement chez certaines espèces animales, mais <span class=\"kw-alerte\">PAS d'effet chez les primates</span>, <span class=\"kw-alerte\">peu efficace voire délétère chez l'Homme</span><br>Régimes hypocaloriques à <span class=\"kw-ci\">proscrire le plus souvent</span> : le substrat consommé en priorité est le <span class=\"kw-clinique\">muscle</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Régime méditerranéen / oméga-3</strong></span></td>\n            <td>Effet protecteur possible : <span class=\"kw-clinique\">cardiovasculaire</span>, <span class=\"kw-clinique\">neurodégénératif</span>, <span class=\"kw-clinique\">cancers</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Anti-oxydants</strong></span></td>\n            <td>Vitamines <span class=\"kw-ttt\">E</span>, <span class=\"kw-ttt\">C</span>, <span class=\"kw-ttt\">A</span>, <span class=\"kw-ttt\">ginkgo biloba</span> — <span class=\"kw-alerte\">TOUTES les études interventionnelles à long terme se sont avérées négatives</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Vitamine D</strong></span></td>\n            <td>Systématique chez <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&gt; 80 ans</span> : prévention de l'<span class=\"kw-clinique\">ostéoporose</span> + de la <span class=\"kw-clinique\">perte de masse musculaire</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>THM</strong></span></td>\n            <td>Sur <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">signes fonctionnels de la ménopause</span> et l'<span class=\"kw-clinique\">ostéoporose</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Principe du « vieillir en forme »</strong>\n        <ul>\n          <li>entretenir le <span class=\"kw-clinique\">capital intellectuel / physique / relationnel</span></li>\n          <li>prévenir <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">maladies évitables</span> (<span class=\"kw-ttt\">grippe</span>, cardiovasculaire)</li>\n          <li>prendre en charge précocement <span class=\"kw-clinique\">les</span> troubles susceptibles d'entraîner des <span class=\"kw-alerte\">désordres en cascade</span> : <span class=\"kw-clinique\">troubles de la marche</span>, <span class=\"kw-clinique\">état dépressif</span>, <span class=\"kw-clinique\">dénutrition</span></li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 124 — Ménopause - andropause · 128 — Ostéopathie fragilisante · 131 — Troubles de la marche et de l'équilibre du sujet âgé · 250 — Dénutrition</em></p>","frequence":0},{"id":"123-18","rang":"B","rubrique":"Définition","titre":"Savoir qualifier le vieillissement sous ses aspects sociologiques et anthropologiques","contenu":"<p>Le <span class=\"kw-def\"><strong>vieillissement réussi</strong></span> intègre <span class=\"kw-def\">tous les aspects psychosociaux propres à chaque individu</span>, plus importants pour la personne que <span class=\"kw-clinique\">les</span> seuls <span class=\"kw-clinique\">aspects médicaux et biologiques</span> : on peut être <span class=\"kw-clinique\">dépendant</span> et avoir un vieillissement réussi.</p>\n      <div class=\"callout callout-info\">\n        <strong>À distinguer du « vieillissement en bonne santé »</strong>\n        <p>Le <span class=\"kw-def\">vieillissement en bonne santé</span> = peu de <span class=\"kw-clinique\">maladies chroniques</span>, <span class=\"kw-clinique\">capacité à réagir au stress</span>, <span class=\"kw-clinique\">vie sans dépendance</span>. <span class=\"kw-clinique\">Les</span> deux notions <span class=\"kw-alerte\">ne sont pas superposables</span>.</p>\n      </div>\n      <p><strong>Aspects sociétaux</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Représentation sociale ambivalente</span> de la personne âgée : négative (affaiblie, inutile) <em><span class=\"kw-bio\">vs</span></em> positive (« patriarche », sagesse, transmission)</li>\n        <li><span class=\"kw-clinique\">Impacts individuels et populationnels</span> du vieillissement</li>\n        <li><span class=\"kw-def\">« Silver économie »</span></li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"23a119e81ca8","n":123,"o":"123-1","u":"Définition","t":"Connaître la définition du vieillissement","q":"Quelle est la définition du vieillissement en médecine ?","a":"<p>Le vieillissement est l'ensemble des <strong>processus physiologiques</strong> qui modifient la structure et les fonctions de l'organisme à partir de l'âge mûr. C'est un processus <strong>lent et progressif</strong>.</p>"},{"i":"34cd1d857a3e","n":123,"o":"123-1","u":"Définition","t":"Connaître la définition du vieillissement","q":"Quels sont les différents types de facteurs qui influencent le vieillissement ?","a":"<ul><li>Facteurs <strong>génétiques</strong></li><li>Facteurs <strong>environnementaux</strong></li><li>Facteurs <strong>aléatoires</strong> (stochastiques)</li></ul>"},{"i":"8046d726f326","n":123,"o":"123-1","u":"Définition","t":"Connaître la définition du vieillissement","q":"Le vieillissement peut-il à lui seul être la cause d'une symptomatologie aiguë ?","a":"<p>Non, le vieillissement n'est <strong>JAMAIS responsable seul</strong> d'une symptomatologie aiguë. L'âge n'explique pas à lui seul une dyspnée, une chute ou une confusion. Une cause doit <strong>toujours être recherchée</strong>.</p>"},{"i":"19b471b17d4f","n":123,"o":"123-14","u":"Définition","t":"Connaître la définition de la fragilité selon Fried (critères) et du déclin fonctionnel","q":"Comment interprète-t-on les critères de Fried pour classer la personne âgée en termes de fragilité ?","a":"<p>L'interprétation se fait selon le nombre de critères de Fried présents :</p><ul><li><strong>Robuste (non fragile)</strong> : 0 critère.</li><li><strong>Préfragile</strong> : 1 à 2 critères.</li><li><strong>Fragile</strong> : ≥ 3 critères.</li></ul>"},{"i":"802bb759abca","n":123,"o":"123-14","u":"Définition","t":"Connaître la définition de la fragilité selon Fried (critères) et du déclin fonctionnel","q":"Quels sont les 5 critères de Fried permettant de diagnostiquer la fragilité chez la personne âgée ?","a":"<p>Les 5 critères de Fried sont :</p><ul><li><strong>Perte de poids involontaire</strong> (dans la dernière année).</li><li><strong>Impression subjective de fatigue</strong>.</li><li><strong>Réduction des activités physiques</strong>.</li><li><strong>Diminution de la force musculaire</strong> (mesurée par <em>handgrip</em>).</li><li><strong>Diminution de la vitesse de marche</strong> (< 0,8 m/s), qui est le critère le plus déterminant.</li></ul>"},{"i":"daeb81c0f51d","n":123,"o":"123-14","u":"Définition","t":"Connaître la définition de la fragilité selon Fried (critères) et du déclin fonctionnel","q":"Quelle est la définition du déclin fonctionnel dans le contexte du vieillissement normal ?","a":"<p>Le déclin fonctionnel est une <strong>réduction multisystémique des réserves fonctionnelles</strong>. La fragilité est considérée comme un <strong>état précurseur de la dépendance fonctionnelle</strong>.</p>"},{"i":"ecb4acd8c8da","n":123,"o":"123-14","u":"Définition","t":"Connaître la définition de la fragilité selon Fried (critères) et du déclin fonctionnel","q":"Selon les critères de Fried, qu'est-ce que la fragilité et combien de critères sont nécessaires pour la définir ?","a":"<p>La fragilité, selon Fried, est un syndrome biologique caractérisé par une <strong>diminution des réserves et de la résistance au stress</strong>. Elle est définie par la présence d'au moins <strong>3 des 5 critères</strong> suivants :</p><ul><li>Perte de poids involontaire.</li><li>Impression subjective de fatigue.</li><li>Réduction des activités physiques.</li><li>Diminution de la force musculaire (mesurée par <em>handgrip</em>).</li><li>Diminution de la vitesse de marche.</li></ul>"},{"i":"4b24d823d297","n":123,"o":"123-2","u":"Définition","t":"Connaître la définition de la gérontologie","q":"Quelle est la définition de la gérontologie ?","a":"<p>La gérontologie est l'étude du vieillissement dans tous ses aspects.</p>"},{"i":"784df780d5a2","n":123,"o":"123-2","u":"Définition","t":"Connaître la définition de la gérontologie","q":"Quelles sont les principales sciences contributrices à la gérontologie ?","a":"<ul><li>La <strong>médecine</strong></li><li>La <strong>sociologie</strong></li><li>La <strong>psychologie</strong></li><li>L'<strong>économie</strong></li><li>La <strong>démographie</strong></li><li>L'<strong>anthropologie</strong></li></ul>"},{"i":"b6a4f49ea406","n":123,"o":"123-2","u":"Définition","t":"Connaître la définition de la gérontologie","q":"Quels sont les différents aspects du vieillissement étudiés en gérontologie ?","a":"<ul><li>Aspect <strong>biomédical</strong></li><li>Aspect <strong>sociologique</strong></li><li>Aspect <strong>géographique</strong></li><li>Aspect <strong>économique</strong></li><li>Aspect <strong>culturel</strong></li><li>Aspect <strong>démographique</strong></li></ul>"},{"i":"6297a4a41bc5","n":123,"o":"123-3","u":"Définition","t":"Connaître la définition de la gériatrie et du raisonnement gériatrique (schéma J.P. Bouchon)","q":"Quelle est la définition de la gériatrie ?","a":"<p>La gériatrie est la <strong>spécialité médicale</strong> qui prend en charge les <strong>personnes âgées</strong>.</p>"},{"i":"8628982722c9","n":123,"o":"123-3","u":"Définition","t":"Connaître la définition de la gériatrie et du raisonnement gériatrique (schéma J.P. Bouchon)","q":"Devant une décompensation aiguë chez une personne âgée, quel facteur doit être recherché et corrigé en priorité selon le modèle de J.P. Bouchon ?","a":"<p>Devant une décompensation aiguë chez une personne âgée, c'est le <strong>facteur 3 (précipitant)</strong> qui doit être traqué et corrigé en priorité. Il est souvent <strong>réversible</strong> et son traitement permet fréquemment le retour à l'état antérieur.</p>"},{"i":"961d080fb080","n":123,"o":"123-3","u":"Définition","t":"Connaître la définition de la gériatrie et du raisonnement gériatrique (schéma J.P. Bouchon)","q":"Selon le modèle de J.P. Bouchon, quels sont les trois facteurs qui contribuent au raisonnement gériatrique et à la décompensation chez une personne âgée ?","a":"<ul><li>Le <strong>vieillissement physiologique de l'organe</strong> (facteur 1) : il correspond à un déclin très progressif des fonctions, sans jamais atteindre à lui seul le seuil d'insuffisance d'organe.</li><li>La <strong>maladie chronique</strong> (facteur 2) : elle diminue la réserve fonctionnelle et est une source de vulnérabilité. Elle peut être absente chez les personnes très âgées.</li><li>Le <strong>facteur précipitant</strong> (facteur 3) : il s'agit d'une situation aiguë qui rend la décompensation symptomatique. C'est souvent le facteur le plus accessible à une intervention et fréquemment réversible.</li></ul>"},{"i":"3df81df7a391","n":123,"o":"123-4","u":"Définition","t":"Connaître la définition de l'âge de la vieillesse","q":"Lorsque l'on parle de risque de perte d'autonomie et de fragilité chez la personne âgée, ou d'entrée en service de gériatrie, quel est l'âge seuil pertinent à considérer ?","a":"<p>Le seuil de risque de perte d'autonomie et de fragilité, ainsi que l'âge d'entrée théorique en service de gériatrie, est de <strong>75 ans</strong>. Cependant, la moyenne réelle d'entrée en gériatrie est <strong>supérieure à 80 ans</strong>.</p>"},{"i":"4bd88020e18e","n":123,"o":"123-4","u":"Définition","t":"Connaître la définition de l'âge de la vieillesse","q":"En France, à partir de quel âge un individu est-il généralement considéré comme personne âgée pour les prestations sociales ?","a":"<p>En France, l'âge de <strong>60 ans</strong> est fréquemment le seuil pris en compte pour l'attribution de certaines prestations sociales.</p>"},{"i":"cdf22c60944c","n":123,"o":"123-4","u":"Définition","t":"Connaître la définition de l'âge de la vieillesse","q":"Selon l'OMS, comment est défini l'âge de la vieillesse ?","a":"<p>L'Organisation Mondiale de la Santé (OMS) fixe la définition de l'âge de la vieillesse à <strong>65 ans</strong>.</p>"},{"i":"61006c517721","n":123,"o":"123-5","u":"Définition","t":"Connaître la définition démographique","q":"Comment définir la longévité maximale chez l'Homme ?","a":"<p>La longévité maximale représente la <strong>durée de vie la plus longue observée</strong> chez un individu de l'espèce, soit <strong>122 ans</strong> pour l'Homme.</p>"},{"i":"66b955229465","n":123,"o":"123-5","u":"Définition","t":"Connaître la définition démographique","q":"Que désigne l'espérance de vie à la naissance pour le vieillissement d'une population ?","a":"<p>L'espérance de vie à la naissance est l'âge auquel <strong>50 % d'une cohorte née la même année décède</strong>. Elle est d'environ <strong>79 ans pour les hommes</strong> et <strong>85 ans pour les femmes</strong> actuellement.</p>"},{"i":"c773aef7d558","n":123,"o":"123-5","u":"Définition","t":"Connaître la définition démographique","q":"Quel indicateur démographique est l'espérance de vie sans incapacité ?","a":"<p>L'espérance de vie sans incapacité est le délai jusqu'à ce que <strong>50 % des personnes décèdent ou soient atteintes d'une incapacité</strong>. La tendance actuelle montre un allongement de la vie s'accompagnant d'une diminution du nombre moyen d'années vécues en incapacité.</p>"},{"i":"f234dc5f5bd4","n":123,"o":"123-5","u":"Définition","t":"Connaître la définition démographique","q":"Quelle est la définition de la longévité moyenne dans le cadre du vieillissement normal ?","a":"<p>La longévité moyenne correspond à la <strong>durée de vie biologiquement programmée</strong> d'une espèce dans des conditions idéales.</p>"},{"i":"bd8eea54251b","n":123,"o":"123-8","u":"Définition","t":"Connaître la définition de l'âgisme","q":"Comment l'évolution sociétale et des connaissances impacte-t-elle l'âgisme ?","a":"<p>L'âgisme est en <strong>voie de régression</strong>, notamment grâce au vieillissement de la population et à l'évolution des connaissances sur le vieillissement.</p>"},{"i":"bf1e09c29025","n":123,"o":"123-8","u":"Définition","t":"Connaître la définition de l'âgisme","q":"Quelle est la définition de l'âgisme d'après l'objectif de l'EDN ?","a":"<p>L'âgisme est une attitude de <strong>discrimination négative</strong> envers les personnes âgées, uniquement du fait de <strong>leur âge</strong>.</p>"},{"i":"240d22520965","n":123,"o":"123-9","u":"Définition","t":"Connaître les notions de vulnérabilité ou fragilité","q":"Qu'est-ce que la vulnérabilité chez la personne âgée ?","a":"<p>La vulnérabilité est une <strong>diminution des capacités de réserve fonctionnelle</strong> de l'organisme. Elle ne se manifeste qu'en cas d'agression (effort, stress, maladie aiguë), rendant la personne symptomatique ou de moins bon pronostic, alors qu'en conditions basales, la personne âgée reste asymptomatique.</p>"},{"i":"c01654e49fd0","n":123,"o":"123-9","u":"Définition","t":"Connaître les notions de vulnérabilité ou fragilité","q":"Qu'est-ce que la fragilité chez la personne âgée et comment est-elle caractérisée ?","a":"<p>La fragilité est un <strong>syndrome gériatrique</strong> facilement mesurable, qui permet d'appréhender globalement la vulnérabilité. Elle est définie par la présence d'au moins <strong>3 des 5 critères de Fried</strong>.</p><ul><li>Toutes les personnes âgées ne sont pas fragiles.</li><li>Elle est associée à un <strong>déclin fonctionnel</strong> et à un risque d'institutionnalisation.</li><li>Elle est <strong>potentiellement réversible</strong> par des interventions comme la nutrition, l'activité physique, l'activité sociale et des traitements adaptés.</li></ul>"},{"i":"cf8a9da8ba4e","n":123,"o":"123-9","u":"Définition","t":"Connaître les notions de vulnérabilité ou fragilité","q":"Quelles sont les deux origines principales de la vulnérabilité chez la personne âgée ?","a":"<ul><li>La vulnérabilité <strong>induite par le vieillissement</strong> normal.</li><li>La vulnérabilité <strong>induite par les séquelles de maladies passées</strong> et les conséquences des maladies chroniques.</li></ul>"}]};